sysauto_script.script:
(function() {
    var THRESHOLD_MINUTES = 8;
    var STATUS_OPERATIONAL = '1';
    var STATUS_NON_OPERATIONAL = '2';

    var gr = new GlideRecord('cmdb_ci_printer');
    gr.addQuery('name', 'npi87c6d5');
    gr.query();

    if (gr.next()) {
        var lastOkStr = gr.getValue('x_1952794_servic_0_last_discovered_ok');
        if (!lastOkStr) {
            return;
        }

        var lastOk = new GlideDateTime(lastOkStr);
        var now = new GlideDateTime();
        var minutesAgo = (now.getNumericValue() - lastOk.getNumericValue()) / 60000;

        var newStatus = (minutesAgo > THRESHOLD_MINUTES) ? STATUS_NON_OPERATIONAL : STATUS_OPERATIONAL;
        var currentStatus = gr.getValue('operational_status');

        //gs.info('DEBUG: minutesAgo=' + minutesAgo + ' currentStatus=' + currentStatus + ' newStatus=' + newStatus);

        if (currentStatus != newStatus) {
            gr.setValue('operational_status', newStatus);
            gr.update();
            gs.info('Printer ' + gr.name + ' operational_status changed to ' + newStatus);
        }
    }
})();
